def card(work):
    metric = lambda out, gold: out.strip().lower() == gold.lower()
    cases = [(f'q{i}', f'a{i}') for i in range(10)]
    train, held = (cases[:6], cases[6:])
    base_out = {q: a if i % 2 == 0 else '?' for i, (q, a) in enumerate(cases)}
    demos = [(q, a) for q, a in train if metric(base_out[q], a)]
    variants = {'base': {q: base_out[q] for q, _ in held}, 'v1': {'q6': 'a6', 'q7': 'a7', 'q8': 'a8', 'q9': '?'}, 'v2': {'q6': '?', 'q7': 'a7', 'q8': 'a8', 'q9': 'a9'}, 'v3': {'q6': 'a6', 'q7': 'a7', 'q8': 'a8', 'q9': 'a9'}}
    score = {v: sum((metric(o[q], a) for q, a in held)) for v, o in variants.items()}
    reg = {v: [q for q, a in held if metric(variants['base'][q], a) and (not metric(variants[v][q], a))] for v in variants}
    winner = max((v for v in variants if v != 'base' and (not reg[v]) and (score[v] > score['base'])), key=score.get, default='base')
    save(work, 'compile.json', {'demos': demos, 'scores': score, 'regressions': reg, 'winner': winner})
    return [eq('demos only from passing train pairs', [q for q, _ in demos], ['q0', 'q2', 'q4']), truth('held-out never used as demos', not {q for q, _ in demos} & {q for q, _ in held}), eq('held-out scores', score, {'base': 2, 'v1': 3, 'v2': 3, 'v3': 4}), eq('v2 regresses q6', reg['v2'], ['q6']), eq('winner', winner, 'v3')]

def card(work):
    cands = {'i1': 'Answer with the number only.', 'i2': 'Reply with only the number.', 'i3': 'First list the known quantities, then compute, then print the result.', 'i4': 'Write Python that computes it and give its output.', 'i5': 'Estimate, then verify by substitution.'}
    distinct = [k for k in cands if all((jaccard(words(cands[k]), words(cands[j])) < 0.5 for j in cands if j < k))]
    scores = {'current': 6, 'i1': 5, 'i3': 7, 'i4': 9, 'i5': 6}
    regress = {'i4': [], 'i3': ['case7'], 'i1': [], 'i5': []}
    best = max((k for k in distinct if k in scores and (not regress[k]) and (scores[k] > scores['current'])), key=scores.get, default='current')
    losers = sorted((k for k in distinct if k != best))
    save(work, 'meta_prompt.json', {'distinct': distinct, 'best': best, 'losers_recorded': losers})
    return [eq('paraphrase removed (i2 ~ i1)', distinct, ['i1', 'i3', 'i4', 'i5']), eq('best without regression', best, 'i4'), eq('losers recorded', losers, ['i1', 'i3', 'i5'])]
